            # Apply transformation
            scale = cfg.get("param_3", 1.0)
            transformed = [x * scale for x in data[:64]]

            # Update history
            result = {
                "step": self._step,
                "method": 3,
                "mean": mean_val,
                "std": std_val,
                "norm": norm_val,
                "scale": scale,
                "n_transformed": len(transformed),
                "timestamp": ts,
            }
            self._history.append(result)
            self._metrics[f"method_3_mean"] = mean_val

            # Fire callbacks
            for cb in self._callbacks.get("method_3", []):
                try: cb(result)
                except Exception as e: logger.warning(f"Callback error: {e}")

            return result

